// Minimal reimplementation - headless part first
use clap::{Arg, ArgAction, Command, value_parser};
use serde::{Deserialize, Serialize};
use std::path::{Path, PathBuf};

fn default_config_dir() -> PathBuf {
    if let Some(d) = dirs::config_dir() {
        d.join("tui-journal")
    } else {
        PathBuf::from(".config/tui-journal")
    }
}
fn default_cache_log() -> PathBuf {
    if let Some(d) = dirs::cache_dir() {
        d.join("tui-journal").join("tui-journal.log")
    } else {
        PathBuf::from(".cache/tui-journal/tui-journal.log")
    }
}
fn default_app_state_dir() -> PathBuf {
    if let Some(d) = dirs::state_dir() {
        d.join("tui-journal")
    } else if let Some(home) = dirs::home_dir() {
        home.join(".local/state/tui-journal")
    } else {
        PathBuf::from(".local/state/tui-journal")
    }
}
fn default_json_path() -> PathBuf {
    if let Some(h) = dirs::home_dir() {
