#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
enum BackendType {
    Json,
    Sqlite,
}
impl Default for BackendType {
    fn default() -> Self { BackendType::Sqlite }
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "snake_case")]
