fn build_cli() -> Command {
    let cfg_default = default_config_dir();
    let cfg_str = cfg_default.to_string_lossy().to_string();
    let log_default = default_cache_log();
    let log_str = log_default.to_string_lossy().to_string();
    Command::new("tui-journal")
        .version("0.16.1")
        .about("Tui app allows writing and managing journals/notes from within the terminal With different local back-ends")
        .arg(Arg::new("json-file-path")
            .short('j')
            .long("json-file-path")
            .value_name("FILE PATH")
            .help("Sets the entries Json file path and starts using it")
            .num_args(1))
        .arg(Arg::new("sqlite-file-path")
            .short('s')
            .long("sqlite-file-path")
            .value_name("FILE PATH")
            .help("Sets the entries sqlite file path and starts using it")
            .num_args(1))
        .arg(Arg::new("backend-type")
            .short('b')
            .long("backend-type")
            .value_name("BACKEND_TYPE")
            .help("Sets the backend type and starts using it")
            .value_parser(value_parser!(String))
            .value_parser(clap::builder::PossibleValuesParser::new(["json", "sqlite"]))
            .num_args(1))
        .arg(Arg::new("config")
            .short('c')
            .long("config")
            .value_name("DIR PATH")
            .help(format!("Specifies the path for the configuration directory.\nConfiguration files is considered as root for themes file too.\nIt still accepts the path for configuration file for backward compatibility.\n(default path: {})", cfg_str))
            .num_args(1))
        .arg(Arg::new("verbose")
            .short('v')
            .long("verbose")
            .help("Increases logging verbosity each use for up to 3 times")
            .action(ArgAction::Count))
        .arg(Arg::new("log")
            .short('l')
            .long("log")
            .value_name("FILE PATH")
            .help(format!("Specifies a file to use for logging\n(default file: {})", log_str))
            .num_args(1))
        .subcommand(Command::new("print-config")
            .about("Print the current settings including the paths for the back-end files")
            .alias("pc"))
        .subcommand(Command::new("import-journals")
            .about("Import journals from the given transfer JSON file to the current back-end file")
            .alias("imj")
            .arg(Arg::new("path")
                .short('p')
                .long("path")
                .value_name("FILE PATH")
                .help("Path of the JSON file to import from")
                .required(true)
                .num_args(1)))
        .subcommand(Command::new("assign-priority")
            .about("Assign priority for all the entries with empty priority field")
            .alias("ap")
            .arg(Arg::new("PRIORITY")
                .help("Priority value (Positive number)")
                .required(true)
                .value_parser(value_parser!(u32))))
        .subcommand(Command::new("theme")
            .about("Provides commands regarding changing themes and styles of the app")
            .alias("style")
            .subcommand_required(true)
            .arg_required_else_help(true)
            .subcommand(Command::new("print-path")
                .about("Prints the path to the user themes file")
                .alias("path"))
            .subcommand(Command::new("print-default")
                .about("Dumps the styles with the default values to be used as a reference and base for user custom themes")
                .alias("default"))
            .subcommand(Command::new("write-defaults")
                .about("Creates user custom themes file if doesn't exist then writes the default styles to it")
                .alias("write")))
}

fn init_logging(log_path: &Path, verbose: u8) -> Result<(), String> {
    // create parent dirs
    if let Some(parent) = log_path.parent() {
        if !parent.as_os_str().is_empty() {
            if let Err(e) = std::fs::create_dir_all(parent) {
                return Err(format!("{} (os error {})", e.to_string().split(" (os error").next().unwrap_or(&e.to_string()), e.raw_os_error().unwrap_or(0)));
            }
        }
    }
    // try to create/open file
    match std::fs::OpenOptions::new().create(true).append(true).open(log_path) {
        Ok(_) => {},
        Err(e) => {
            let code = e.raw_os_error().unwrap_or(0);
            let msg = match code {
                21 => "Is a directory",
                13 => "Permission denied",
                2 => "No such file or directory",
                _ => &e.to_string(),
            };
            // Need exact format: "Error: <msg> (os error <code>)"
            // For Is a directory, original says "Error: Is a directory (os error 21)"
            // For Permission denied, "Error: Permission denied (os error 13)"
            return Err(format!("{} (os error {})", msg, code));
        }
    }
    if verbose >= 3 {
        // append trace line
        let now = chrono::Local::now();
        let time_str = now.format("%H:%M:%S").to_string();
        let line = format!("{} [TRACE] (1) tjournal::logging: [src/logging.rs:38] Log initialized with level: TRACE\n", time_str);
        if let Ok(mut f) = std::fs::OpenOptions::new().append(true).open(log_path) {
            use std::io::Write;
            let _ = f.write_all(line.as_bytes());
        }
    }
    Ok(())
}

fn resolve_config_path(custom: Option<&str>) -> Result<(Option<PathBuf>, PathBuf, bool), String> {
    // returns (config_file_path or None, theme_dir, is_file?)
    // theme_dir is dir for themes.toml
    // if custom is None: config file is default_config_dir/config.toml if exists else None, theme dir is default_config_dir
    // if custom is Some(p): if p doesn't exist => error
    //   if p is dir: config file is p/config.toml if exists else None, theme dir is p
    //   if p is file: config file is p, theme dir is default (with INFO)
    if let Some(p_str) = custom {
        let p = PathBuf::from(p_str);
        if !p.exists() {
            return Err(format!("Provided custom directory doesn't exit. Path: {}", p_str));
        }
        if p.is_dir() {
            let cfg = p.join("config.toml");
            let cfg_opt = if cfg.exists() { Some(cfg) } else { None };
            Ok((cfg_opt, p, false))
        } else {
            // file
            Ok((Some(p), default_config_dir(), true))
        }
    } else {
        let def_dir = default_config_dir();
        let cfg = def_dir.join("config.toml");
        let cfg_opt = if cfg.exists() { Some(cfg) } else { None };
        Ok((cfg_opt, def_dir, false))
    }
}

fn load_settings(config_file: Option<&PathBuf>) -> Result<Settings, String> {
    let mut settings = Settings::default();
    // Need to recompute defaults based on current HOME? Already done in Default.
    // But if config file exists, parse and merge? Actually serde will fill missing with defaults if we deserialize directly?
    // We need to handle unknown fields ignored, and error messages exactly.
    // Simplest: deserialize file content to Settings with defaults for missing.
    // But Settings::default() uses current HOME for paths, which is correct.
    // For merging, we can deserialize to a struct with Option fields? Easier: read file, parse with toml, then deserialize.
    // However, toml deserialization of Settings directly will use defaults for missing fields (via #[serde(default)]), but for nested structs?
    // That should work. But file_path defaults need to be current HOME-based, which our Default impl does.
    // So just do: let content = fs::read_to_string(...)?; toml::from_str::<Settings>(&content).map_err(...)
    if let Some(cfg_path) = config_file {
        let content = std::fs::read_to_string(cfg_path).map_err(|e| {
            format!("Failed to read configuration file. Error infos: {}", e)
        })?;
        // Use toml parsing to get same error messages as original
        let parsed: Settings = toml::from_str(&content).map_err(|e| {
            format!("Failed to read configuration file. Error infos: {}", e)
        })?;
        settings = parsed;
        // Need to handle that file_path defaults in nested structs might have been from Default at parse time?
        // toml crate will use Default for missing file_path? Our structs have #[serde(default = "...")] for file_path, but that function uses current HOME.
        // Should be correct.
        // However, app_state_dir, json/sqlite paths in file are absolute or relative? Keep as is.
    }
    Ok(settings)
}

fn main() {
    let cli = build_cli();
    let matches = cli.try_get_matches();
    let matches = match matches {
        Ok(m) => m,
        Err(e) => {
            // clap errors go to stderr with exit 2, except help/version go to stdout with exit 0
