fn init_logging(log_path: &Path, verbose: u8) -> Result<(), String> {
    // create parent dirs
    if let Some(parent) = log_path.parent() {
        if !parent.as_os_str().is_empty() {
            if let Err(e) = std::fs::create_dir_all(parent) {
                return Err(format!("{} (os error {})", e.to_string().split(" (os error").next().unwrap_or(&e.to_string()), e.raw_os_error().unwrap_or(0)));
            }
        }
    }
    // try to create/open file
    match std::fs::OpenOptions::new().create(true).append(true).open(log_path) {
        Ok(_) => {},
        Err(e) => {
            let code = e.raw_os_error().unwrap_or(0);
            let msg = match code {
                21 => "Is a directory",
                13 => "Permission denied",
                2 => "No such file or directory",
                _ => &e.to_string(),
            };
            // Need exact format: "Error: <msg> (os error <code>)"
            // For Is a directory, original says "Error: Is a directory (os error 21)"
            // For Permission denied, "Error: Permission denied (os error 13)"
            return Err(format!("{} (os error {})", msg, code));
        }
    }
    if verbose >= 3 {
        // append trace line
        let now = chrono::Local::now();
        let time_str = now.format("%H:%M:%S").to_string();
        let line = format!("{} [TRACE] (1) tjournal::logging: [src/logging.rs:38] Log initialized with level: TRACE\n", time_str);
        if let Ok(mut f) = std::fs::OpenOptions::new().append(true).open(log_path) {
            use std::io::Write;
            let _ = f.write_all(line.as_bytes());
        }
    }
    Ok(())
}

fn resolve_config_path(custom: Option<&str>) -> Result<(Option<PathBuf>, PathBuf, bool), String> {
    // returns (config_file_path or None, theme_dir, is_file?)
    // theme_dir is dir for themes.toml
    // if custom is None: config file is default_config_dir/config.toml if exists else None, theme dir is default_config_dir
    // if custom is Some(p): if p doesn't exist => error
    //   if p is dir: config file is p/config.toml if exists else None, theme dir is p
    //   if p is file: config file is p, theme dir is default (with INFO)
    if let Some(p_str) = custom {
        let p = PathBuf::from(p_str);
        if !p.exists() {
            return Err(format!("Provided custom directory doesn't exit. Path: {}", p_str));
        }
        if p.is_dir() {
            let cfg = p.join("config.toml");
            let cfg_opt = if cfg.exists() { Some(cfg) } else { None };
            Ok((cfg_opt, p, false))
        } else {
            // file
            Ok((Some(p), default_config_dir(), true))
        }
    } else {
        let def_dir = default_config_dir();
        let cfg = def_dir.join("config.toml");
        let cfg_opt = if cfg.exists() { Some(cfg) } else { None };
        Ok((cfg_opt, def_dir, false))
    }
}

