    // But Settings::default() uses current HOME for paths, which is correct.
    // For merging, we can deserialize to a struct with Option fields? Easier: read file, parse with toml, then deserialize.
    // However, toml deserialization of Settings directly will use defaults for missing fields (via #[serde(default)]), but for nested structs?
    // That should work. But file_path defaults need to be current HOME-based, which our Default impl does.
    // So just do: let content = fs::read_to_string(...)?; toml::from_str::<Settings>(&content).map_err(...)
    if let Some(cfg_path) = config_file {
        let content = std::fs::read_to_string(cfg_path).map_err(|e| {
            format!("Failed to read configuration file. Error infos: {}", e)
        })?;
        // Use toml parsing to get same error messages as original
        let parsed: Settings = toml::from_str(&content).map_err(|e| {
            format!("Failed to read configuration file. Error infos: {}", e)
        })?;
        settings = parsed;
        // Need to handle that file_path defaults in nested structs might have been from Default at parse time?
        // toml crate will use Default for missing file_path? Our structs have #[serde(default = "...")] for file_path, but that function uses current HOME.
        // Should be correct.
        // However, app_state_dir, json/sqlite paths in file are absolute or relative? Keep as is.
    }
    Ok(settings)
}

fn main() {
    let cli = build_cli();
    let matches = cli.try_get_matches();
    let matches = match matches {
        Ok(m) => m,
        Err(e) => {
            // clap errors go to stderr with exit 2, except help/version go to stdout with exit 0
            // e.exit() handles that
            e.exit();
        }
    };

    let verbose = matches.get_count("verbose") as u8;
    let custom_log: Option<String> = matches.get_one::<String>("log").cloned();
    let log_path: PathBuf = if let Some(p) = custom_log {
        PathBuf::from(p)
    } else {
        default_cache_log()
    };

    // init logging first (before config?)
    if let Err(msg) = init_logging(&log_path, verbose) {
        eprintln!("Error: {}", msg);
        std::process::exit(1);
    }

    let custom_config: Option<String> = matches.get_one::<String>("config").cloned();
    let custom_config_opt = custom_config.as_deref();

    // resolve config path
    let (config_file_opt, theme_dir, is_file) = match resolve_config_path(custom_config_opt) {
        Ok(v) => v,
        Err(msg) => {
            eprintln!("Error: {}", msg);
            std::process::exit(1);
        }
    };

    // load settings
    let mut settings = match load_settings(config_file_opt.as_ref()) {
        Ok(s) => s,
        Err(msg) => {
            eprintln!("Error: {}", msg);
            std::process::exit(1);
        }
    };

    // apply CLI overrides
    if let Some(j) = matches.get_one::<String>("json-file-path") {
        settings.json_backend.file_path = PathBuf::from(j);
        // set backend to Json unless overridden by -s or -b? Handle below
    }
    if let Some(s) = matches.get_one::<String>("sqlite-file-path") {
        settings.sqlite_backend.file_path = PathBuf::from(s);
    }
    // backend logic
    let cli_backend: Option<String> = matches.get_one::<String>("backend-type").cloned();
    let has_j = matches.contains_id("json-file-path");
    let has_s = matches.contains_id("sqlite-file-path");
    // Actually contains_id returns true even if not present? Use get_one is_some
    let has_j = matches.get_one::<String>("json-file-path").is_some();
    let has_s = matches.get_one::<String>("sqlite-file-path").is_some();
    if let Some(b) = cli_backend {
        if b == "json" {
            settings.backend_type = BackendType::Json;
        } else if b == "sqlite" {
            settings.backend_type = BackendType::Sqlite;
        }
    } else {
        if has_s {
            settings.backend_type = BackendType::Sqlite;
        } else if has_j {
            settings.backend_type = BackendType::Json;
        }
    }

    // handle subcommands
    if let Some((sub, sub_matches)) = matches.subcommand() {
        match sub {
            "print-config" | "pc" => {
                // serialize settings to TOML exactly
                let out = toml::to_string(&settings).unwrap();
                print!("{}", out);
                // toml::to_string adds trailing newline? Check: our earlier ref shows trailing newline + extra blank line? Actually print_config ends with "\n\n"? Let's see: file ends with "...entries.db\"\n\n" (with blank line). toml::to_string likely ends with "\n". Need to ensure exactly one trailing newline? Our ref shows file ends with "\n" then extra "\n"? Actually data ends with "\"\n\n" meaning last line plus blank line. That's because toml serialization adds newline after each table? Let's just print as is and adjust later.
                // Ensure output ends with newline? toml::to_string already ends with newline.
                // But need to check: our ref print_config ends with "\n\n"? Wait earlier python showed data ends with "...entries.db\"\n\n" (two newlines?) Actually repr showed "...entries.db\"\n\n" - that's one line content plus blank line? Let's check: last lines are "[sqlite_backend]\nfile_path = \"...\"\n\n" - that's table header, file_path line, then blank line (extra \n). So total ends with \n\n? No, file_path line ends with \n, then blank line is \n, so ends with \n\n? Actually file_path line is "file_path = \"...\"\n", then blank line is "\n", so file ends with "\n\n"? But our earlier len 464 includes that. toml::to_string likely produces exactly that (with trailing newline, but does it add extra blank line at end?). We'll test.
                return;
            },
            "theme" | "style" => {
                if let Some((tsub, _)) = sub_matches.subcommand() {
                    match tsub {
                        "print-path" | "path" => {
                            let theme_path = if is_file {
                                eprintln!("INFO: Custom config directory is ignored in themese because it's not a directory.");
                                default_config_dir().join("themes.toml")
                            } else {
                                theme_dir.join("themes.toml")
                            };
                            println!("{}", theme_path.to_string_lossy());
                            return;
                        },
                        "print-default" | "default" => {
                            let def = default_themes_toml();
                            print!("{}", def);
                            return;
                        },
                        "write-defaults" | "write" => {
                            let theme_path = if is_file {
                                eprintln!("INFO: Custom config directory is ignored in themese because it's not a directory.");
                                default_config_dir().join("themes.toml")
                            } else {
                                theme_dir.join("themes.toml")
                            };
                            // check parent exists?
                            if let Some(parent) = theme_path.parent() {
                                if !parent.exists() {
                                    eprintln!("Error: Error while writing default themes to file");
                                    eprintln!("");
                                    eprintln!("Caused by:");
                                    eprintln!("    No such file or directory (os error 2)");
                                    std::process::exit(1);
                                }
                            }
                            if theme_path.exists() {
                                eprintln!("Error: Themes file already exists. Path: {}", theme_path.to_string_lossy());
                                std::process::exit(1);
                            }
                            let def = default_themes_toml_file();
                            match std::fs::write(&theme_path, def) {
                                Ok(_) => {
                                    println!("Default themes have been written to {}", theme_path.to_string_lossy());
                                },
                                Err(e) => {
                                    let code = e.raw_os_error().unwrap_or(0);
                                    let msg = match code {
                                        2 => "No such file or directory",
                                        _ => "Unknown",
                                    };
                                    eprintln!("Error: Error while writing default themes to file");
                                    eprintln!("");
                                    eprintln!("Caused by:");
                                    eprintln!("    {} (os error {})", msg, code);
                                    std::process::exit(1);
                                }
                            }
                            return;
                        },
                        _ => {}
                    }
                }
                return;
            },
            "import-journals" | "imj" => {
                let import_path = sub_matches.get_one::<String>("path").unwrap().clone();
                // For now, need to launch TUI (requires tty). If no tty, error ENXIO.
                // Try to init terminal; if fails, print error and exit 1.
                // We'll implement TUI later; for now, just attempt to run TUI stub.
                run_tui_with_import(settings, theme_dir, Some(import_path), None);
                return;
            },
            "assign-priority" | "ap" => {
                let prio = *sub_matches.get_one::<u32>("PRIORITY").unwrap();
                run_tui_with_import(settings, theme_dir, None, Some(prio));
                return;
            },
            _ => {}
        }
    } else {
        // no subcommand: launch TUI
        run_tui_with_import(settings, theme_dir, None, None);
        return;
    }
}

