fn deserialize_opt_color<'de, D>(deserializer: D) -> Result<Option<ThemeColor>, D::Error>
where D: serde::Deserializer<'de> {
    use serde::de::{self, Visitor};
    struct OptColorVisitor;
    impl<'de> Visitor<'de> for OptColorVisitor {
        type Value = Option<ThemeColor>;
        fn expecting(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result { write!(f, "a color") }
        fn visit_none<E>(self) -> Result<Self::Value, E> where E: de::Error { Ok(None) }
        fn visit_unit<E>(self) -> Result<Self::Value, E> where E: de::Error { Ok(None) }
        fn visit_some<D>(self, deserializer: D) -> Result<Self::Value, D::Error> where D: serde::Deserializer<'de> {
            deserializer.deserialize_any(ColorVisitor).map(Some)
        }
        fn visit_str<E>(self, v: &str) -> Result<Self::Value, E> where E: de::Error {
            match parse_color_value(v) {
                Ok(_) => Ok(Some(ThemeColor(v.to_string()))),
                Err(msg) => Err(E::custom(msg)),
            }
        }
        fn visit_string<E>(self, v: String) -> Result<Self::Value, E> where E: de::Error {
            match parse_color_value(&v) {
                Ok(_) => Ok(Some(ThemeColor(v))),
                Err(msg) => Err(E::custom(msg)),
            }
        }
    }
    struct ColorVisitor;
    impl<'de> Visitor<'de> for ColorVisitor {
        type Value = ThemeColor;
        fn expecting(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result { write!(f, "a color") }
        fn visit_str<E>(self, v: &str) -> Result<Self::Value, E> where E: de::Error {
            match parse_color_value(v) {
                Ok(_) => Ok(ThemeColor(v.to_string())),
                Err(msg) => Err(E::custom(msg)),
            }
        }
        fn visit_string<E>(self, v: String) -> Result<Self::Value, E> where E: de::Error {
            match parse_color_value(&v) {
                Ok(_) => Ok(ThemeColor(v)),
                Err(msg) => Err(E::custom(msg)),
            }
        }
        fn visit_bool<E>(self, v: bool) -> Result<Self::Value, E> where E: de::Error {
            Err(E::custom("Failed to parse Colors: data did not match any variant of untagged enum ColorFormat"))
        }
        fn visit_i64<E>(self, v: i64) -> Result<Self::Value, E> where E: de::Error {
            Err(E::custom("Failed to parse Colors: data did not match any variant of untagged enum ColorFormat"))
        }
        fn visit_u64<E>(self, v: u64) -> Result<Self::Value, E> where E: de::Error {
            Err(E::custom("Failed to parse Colors: data did not match any variant of untagged enum ColorFormat"))
        }
        fn visit_f64<E>(self, v: f64) -> Result<Self::Value, E> where E: de::Error {
            Err(E::custom("Failed to parse Colors: data did not match any variant of untagged enum ColorFormat"))
        }
    }
    deserializer.deserialize_option(OptColorVisitor)
}

