    let csql = CString::new(sql).unwrap();
    let mut stmt: *mut c_void = std::ptr::null_mut();
    let rc = unsafe { sqlite3_prepare_v2(db, csql.as_ptr(), -1, &mut stmt, std::ptr::null_mut()) };
    if rc != SQLITE_OK {
        let e = sqlite_err(db);
        sqlite_close(db);
        return Err(e);
    }
    loop {
        let rc = unsafe { sqlite3_step(stmt) };
        if rc == SQLITE_ROW {
            let id = unsafe { sqlite3_column_int(stmt, 0) } as u32;
            let title_ptr = unsafe { sqlite3_column_text(stmt, 1) };
            let title = if title_ptr.is_null() { String::new() } else { unsafe { CStr::from_ptr(title_ptr as *const c_char).to_string_lossy().to_string() } };
            let date_ptr = unsafe { sqlite3_column_text(stmt, 2) };
            let date_str = if date_ptr.is_null() { String::new() } else { unsafe { CStr::from_ptr(date_ptr as *const c_char).to_string_lossy().to_string() } };
            let content_ptr = unsafe { sqlite3_column_text(stmt, 3) };
            let content = if content_ptr.is_null() { String::new() } else { unsafe { CStr::from_ptr(content_ptr as *const c_char).to_string_lossy().to_string() } };
            let prio_type = unsafe { sqlite3_column_type(stmt, 4) };
            let priority = if prio_type == SQLITE_NULL { None } else { Some(unsafe { sqlite3_column_int(stmt, 4) } as u32) };
            // Parse date
            let date = DateTime::parse_from_rfc3339(&date_str).map(|d| d.with_timezone(&Utc)).unwrap_or_else(|_| Utc::now());
            // Load tags for this entry
            let tags = load_sqlite_tags(db, id);
            entries.push(Entry { id, date, title, content, tags, priority });
        } else if rc == SQLITE_DONE {
            break;
        } else {
            let e = sqlite_err(db);
            unsafe { sqlite3_finalize(stmt); }
            sqlite_close(db);
            return Err(e);
        }
    }
    unsafe { sqlite3_finalize(stmt); }
    sqlite_close(db);
    Ok(entries)
}

fn load_sqlite_tags(db: *mut c_void, entry_id: u32) -> Vec<String> {
    let sql = format!("SELECT tag FROM tags WHERE entry_id = {} ORDER BY tag", entry_id);
    let csql = CString::new(sql).unwrap();
    let mut stmt: *mut c_void = std::ptr::null_mut();
    let rc = unsafe { sqlite3_prepare_v2(db, csql.as_ptr(), -1, &mut stmt, std::ptr::null_mut()) };
    if rc != SQLITE_OK { return vec![]; }
    let mut tags = Vec::new();
    loop {
        let rc = unsafe { sqlite3_step(stmt) };
        if rc == SQLITE_ROW {
            let ptr = unsafe { sqlite3_column_text(stmt, 0) };
            if !ptr.is_null() {
                let s = unsafe { CStr::from_ptr(ptr as *const c_char).to_string_lossy().to_string() };
                tags.push(s);
            }
        } else { break; }
    }
    unsafe { sqlite3_finalize(stmt); }
    tags
