fn load_sqlite_entries(db_path: &Path) -> Result<Vec<Entry>, String> {
    if !db_path.exists() {
        return Ok(vec![]);
    }
    // Check if file is valid sqlite? If corrupt, return error? Original shows popup for corrupt json, but for sqlite corrupt? Probably similar popup. For now, try to open and query; if fails, return error string for popup.
    let db = ensure_sqlite_schema(db_path)?;
    let mut entries = Vec::new();
    // Query entries
    let sql = "SELECT id, title, date, content, priority FROM entries ORDER BY id";
    let csql = CString::new(sql).unwrap();
    let mut stmt: *mut c_void = std::ptr::null_mut();
    let rc = unsafe { sqlite3_prepare_v2(db, csql.as_ptr(), -1, &mut stmt, std::ptr::null_mut()) };
    if rc != SQLITE_OK {
        let e = sqlite_err(db);
        sqlite_close(db);
        return Err(e);
    }
    loop {
        let rc = unsafe { sqlite3_step(stmt) };
        if rc == SQLITE_ROW {
            let id = unsafe { sqlite3_column_int(stmt, 0) } as u32;
            let title_ptr = unsafe { sqlite3_column_text(stmt, 1) };
            let title = if title_ptr.is_null() { String::new() } else { unsafe { CStr::from_ptr(title_ptr as *const c_char).to_string_lossy().to_string() } };
            let date_ptr = unsafe { sqlite3_column_text(stmt, 2) };
            let date_str = if date_ptr.is_null() { String::new() } else { unsafe { CStr::from_ptr(date_ptr as *const c_char).to_string_lossy().to_string() } };
            let content_ptr = unsafe { sqlite3_column_text(stmt, 3) };
            let content = if content_ptr.is_null() { String::new() } else { unsafe { CStr::from_ptr(content_ptr as *const c_char).to_string_lossy().to_string() } };
            let prio_type = unsafe { sqlite3_column_type(stmt, 4) };
            let priority = if prio_type == SQLITE_NULL { None } else { Some(unsafe { sqlite3_column_int(stmt, 4) } as u32) };
            // Parse date
            let date = DateTime::parse_from_rfc3339(&date_str).map(|d| d.with_timezone(&Utc)).unwrap_or_else(|_| Utc::now());
            // Load tags for this entry
            let tags = load_sqlite_tags(db, id);
            entries.push(Entry { id, date, title, content, tags, priority });
        } else if rc == SQLITE_DONE {
            break;
        } else {
            let e = sqlite_err(db);
            unsafe { sqlite3_finalize(stmt); }
            sqlite_close(db);
            return Err(e);
        }
    }
    unsafe { sqlite3_finalize(stmt); }
    sqlite_close(db);
    Ok(entries)
}

fn load_sqlite_tags(db: *mut c_void, entry_id: u32) -> Vec<String> {
    let sql = format!("SELECT tag FROM tags WHERE entry_id = {} ORDER BY tag", entry_id);
    let csql = CString::new(sql).unwrap();
    let mut stmt: *mut c_void = std::ptr::null_mut();
    let rc = unsafe { sqlite3_prepare_v2(db, csql.as_ptr(), -1, &mut stmt, std::ptr::null_mut()) };
    if rc != SQLITE_OK { return vec![]; }
    let mut tags = Vec::new();
    loop {
        let rc = unsafe { sqlite3_step(stmt) };
        if rc == SQLITE_ROW {
            let ptr = unsafe { sqlite3_column_text(stmt, 0) };
            if !ptr.is_null() {
                let s = unsafe { CStr::from_ptr(ptr as *const c_char).to_string_lossy().to_string() };
                tags.push(s);
            }
        } else { break; }
    }
    unsafe { sqlite3_finalize(stmt); }
    tags
}

fn save_sqlite_entries(db_path: &Path, entries: &[Entry]) -> Result<(), String> {
    if let Some(parent) = db_path.parent() {
        if !parent.as_os_str().is_empty() {
            std::fs::create_dir_all(parent).map_err(|e| e.to_string())?;
        }
    }
    let db = ensure_sqlite_schema(db_path)?;
    // For simplicity, delete all and re-insert? Original likely does upserts, but for our purposes (import append, assign update, create), we need to handle correctly.
    // Instead, we'll implement: clear and re-insert all (with same IDs). This works for import (which loads existing + new, then saves all) and assign (updates in place).
    // But need to handle tags too.
    // Clear
    for sql in ["DELETE FROM tags", "DELETE FROM entries"] {
        let csql = CString::new(sql).unwrap();
        let mut errmsg: *mut c_char = std::ptr::null_mut();
        let rc = unsafe { sqlite3_exec(db, csql.as_ptr(), None, std::ptr::null_mut(), &mut errmsg) };
        if rc != SQLITE_OK {
            unsafe { if !errmsg.is_null() { sqlite3_free(errmsg as *mut c_void); } }
        }
    }
    for e in entries {
        let date_str = e.date.to_rfc3339_opts(chrono::SecondsFormat::AutoSi, false);
        // Escape single quotes by doubling?
        let title_esc = e.title.replace("'", "''");
        let content_esc = e.content.replace("'", "''");
        let prio_str = match e.priority { Some(p) => p.to_string(), None => "NULL".to_string() };
        let sql = format!("INSERT INTO entries (id, title, date, content, priority) VALUES ({}, '{}', '{}', '{}', {})", e.id, title_esc, date_str, content_esc, prio_str);
        let csql = CString::new(sql).unwrap();
        let mut errmsg: *mut c_char = std::ptr::null_mut();
        let rc = unsafe { sqlite3_exec(db, csql.as_ptr(), None, std::ptr::null_mut(), &mut errmsg) };
        if rc != SQLITE_OK {
            unsafe { if !errmsg.is_null() { sqlite3_free(errmsg as *mut c_void); } }
        }
        for tag in &e.tags {
            let tag_esc = tag.replace("'", "''");
            let sql2 = format!("INSERT OR IGNORE INTO tags (entry_id, tag) VALUES ({}, '{}')", e.id, tag_esc);
            let csql2 = CString::new(sql2).unwrap();
            let mut errmsg2: *mut c_char = std::ptr::null_mut();
            let _ = unsafe { sqlite3_exec(db, csql2.as_ptr(), None, std::ptr::null_mut(), &mut errmsg2) };
            unsafe { if !errmsg2.is_null() { sqlite3_free(errmsg2 as *mut c_void); } }
        }
    }
    sqlite_close(db);
    Ok(())
}

fn load_entries(settings: &Settings) -> Result<Vec<Entry>, String> {
    match settings.backend_type {
        BackendType::Json => load_json_entries(&settings.json_backend.file_path),
        BackendType::Sqlite => load_sqlite_entries(&settings.sqlite_backend.file_path),
    }
}

fn save_entries(settings: &Settings, entries: &[Entry]) -> Result<(), String> {
    match settings.backend_type {
        BackendType::Json => save_json_entries(&settings.json_backend.file_path, entries),
        BackendType::Sqlite => save_sqlite_entries(&settings.sqlite_backend.file_path, entries),
    }
}

