                                let date = parse_create_date(&create_date);
                                let priority = if create_priority.trim().is_empty() { None } else { create_priority.trim().parse::<u32>().ok() };
                                let tags: Vec<String> = create_tags.split(|c| c==',' || c==' ' || c==';').filter(|s| !s.trim().is_empty()).map(|s| s.trim().to_string()).collect();
                                let next_id = entries.iter().map(|e| e.id).max().map(|m| m+1).unwrap_or(0);
                                let new_entry = Entry { id: next_id, date, title, content: String::new(), tags, priority };
