                                create_title.clear();
                                create_priority.clear();
                                create_tags.clear();
                                create_date = chrono::Local::now().format("%d-%m-%Y").to_string();
                                create_field = 0;
                                continue;
                            }
                            // Regular typing to current field
                            match create_field {
                                0 => create_title.push(c),
                                1 => create_date.push(c),
                                2 => create_priority.push(c),
                                3 => create_tags.push(c),
                                _ => {}
                            }
                            continue;
                        },
                        KeyCode::Backspace => {
                            match create_field {
                                0 => { create_title.pop(); },
                                1 => { create_date.pop(); },
                                2 => { create_priority.pop(); },
                                3 => { create_tags.pop(); },
