fn centered_rect(percent_x: u16, percent_y: u16, r: ratatui::layout::Rect) -> ratatui::layout::Rect {
    use ratatui::layout::{Constraint, Direction, Layout};
    let popup_layout = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Percentage((100 - percent_y) / 2),
            Constraint::Percentage(percent_y),
            Constraint::Percentage((100 - percent_y) / 2),
        ])
        .split(r);
    Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage((100 - percent_x) / 2),
            Constraint::Percentage(percent_x),
            Constraint::Percentage((100 - percent_x) / 2),
        ])
        .split(popup_layout[1])[1]
}

fn parse_create_date(s: &str) -> DateTime<Utc> {
    // Expect DD-MM-YYYY, else use today midnight UTC
    let s = s.trim();
    if let Ok(d) = chrono::NaiveDate::parse_from_str(s, "%d-%m-%Y") {
        let dt = d.and_hms_opt(0,0,0).unwrap();
        return DateTime::<Utc>::from_naive_utc_and_offset(dt, Utc);
    }
    // Try other formats? For now, today
    let today = chrono::Local::now().date_naive();
    let dt = today.and_hms_opt(0,0,0).unwrap();
    DateTime::<Utc>::from_naive_utc_and_offset(dt, Utc)
}
