                let chunks = Layout::default()
                    .direction(Direction::Vertical)
                    .constraints([Constraint::Length(3), Constraint::Length(3), Constraint::Length(3), Constraint::Length(3), Constraint::Min(1)])
                    .split(inner);
                // Title
                let title_block = Block::default().title("Title").borders(Borders::ALL);
                let title_inner = title_block.inner(chunks[0]);
                f.render_widget(title_block, chunks[0]);
                f.render_widget(Paragraph::new(create_title.clone()), title_inner);
                // Date
                let date_block = Block::default().title("Date").borders(Borders::ALL);
                let date_inner = date_block.inner(chunks[1]);
                f.render_widget(date_block, chunks[1]);
                f.render_widget(Paragraph::new(create_date.clone()), date_inner);
                // Priority
                let prio_block = Block::default().title("Priority").borders(Borders::ALL);
                let prio_inner = prio_block.inner(chunks[2]);
                f.render_widget(prio_block, chunks[2]);
                f.render_widget(Paragraph::new(create_priority.clone()), prio_inner);
                // Tags
                let tags_block = Block::default().title("Tags").borders(Borders::ALL);
                let tags_inner = tags_block.inner(chunks[3]);
                f.render_widget(tags_block, chunks[3]);
                f.render_widget(Paragraph::new(create_tags.clone()), tags_inner);
                // Footer
                let footer = Paragraph::new("Enter or <Ctrl-m>: confirm | Esc or <Ctrl-c>: Cancel | Tab: Change focused control | <Ctrl-Space> or <Ctrl-t>: Open tags");
                f.render_widget(footer, chunks[4]);
            }
        }).unwrap();

        // Handle input with timeout to allow loading popup to disappear
        if event::poll(std::time::Duration::from_millis(100)).unwrap() {
            if let Event::Key(key) = event::read().unwrap() {
                // If error popup shown, handle dismissal
                if error_popup.is_some() {
                    match key.code {
                        KeyCode::Enter | KeyCode::Esc => { error_popup = None; continue; },
                        KeyCode::Char('o') => { error_popup = None; continue; },
                        _ => { continue; }
                    }
                }
                if show_help {
                    match key.code {
                        KeyCode::Esc | KeyCode::Char('q') => { show_help = false; continue; },
                        _ => { continue; }
                    }
                }
                if show_create {
                    match key.code {
                        KeyCode::Esc => {
                            if key.modifiers.contains(KeyModifiers::CONTROL) {
                                show_create = false;
                            } else {
                                show_create = false;
                            }
                            continue;
