                            // Confirm (also Ctrl-m which is Enter)
                            // Validate and save
                            let title = create_title.trim().to_string();
                            // Parse date: expect DD-MM-YYYY, convert to Utc midnight
                            let date = parse_create_date(&create_date);
                            let priority = if create_priority.trim().is_empty() { None } else { create_priority.trim().parse::<u32>().ok() };
                            let tags: Vec<String> = create_tags.split(|c| c==',' || c==' ' || c==';').filter(|s| !s.trim().is_empty()).map(|s| s.trim().to_string()).collect();
                            let next_id = entries.iter().map(|e| e.id).max().map(|m| m+1).unwrap_or(0);
                            let new_entry = Entry { id: next_id, date, title, content: String::new(), tags, priority };
                            entries.push(new_entry);
                            entries.sort_by_key(|e| e.id);
                            let _ = save_entries(&settings, &entries);
                            selected = entries.len().saturating_sub(1);
                            show_create = false;
                            create_title.clear();
                            create_priority.clear();
                            create_tags.clear();
                            create_date = chrono::Local::now().format("%d-%m-%Y").to_string();
                            create_field = 0;
                            continue;
                        },
                        KeyCode::Tab => {
                            create_field = (create_field + 1) % 4;
                            continue;
                        },
                        KeyCode::BackTab => {
                            create_field = (create_field + 3) % 4;
                            continue;
                        },
                        KeyCode::Char(c) => {
                            // Ctrl-c cancels? Already handled Esc, but Ctrl-c also cancels
                            if key.modifiers.contains(KeyModifiers::CONTROL) && (c=='c' || c=='C') {
                                show_create = false;
                                continue;
                            }
                            if key.modifiers.contains(KeyModifiers::CONTROL) && (c=='m' || c=='M') {
                                // Ctrl-m confirms (same as Enter)
                                let title = create_title.trim().to_string();
                                let date = parse_create_date(&create_date);
                                let priority = if create_priority.trim().is_empty() { None } else { create_priority.trim().parse::<u32>().ok() };
                                let tags: Vec<String> = create_tags.split(|c| c==',' || c==' ' || c==';').filter(|s| !s.trim().is_empty()).map(|s| s.trim().to_string()).collect();
                                let next_id = entries.iter().map(|e| e.id).max().map(|m| m+1).unwrap_or(0);
                                let new_entry = Entry { id: next_id, date, title, content: String::new(), tags, priority };
                                entries.push(new_entry);
                                entries.sort_by_key(|e| e.id);
                                let _ = save_entries(&settings, &entries);
                                selected = entries.len().saturating_sub(1);
                                show_create = false;
                                create_title.clear();
                                create_priority.clear();
                                create_tags.clear();
                                create_date = chrono::Local::now().format("%d-%m-%Y").to_string();
                                create_field = 0;
                                continue;
                            }
                            // Regular typing to current field
                            match create_field {
                                0 => create_title.push(c),
                                1 => create_date.push(c),
                                2 => create_priority.push(c),
                                3 => create_tags.push(c),
                                _ => {}
                            }
                            continue;
                        },
                        KeyCode::Backspace => {
                            match create_field {
                                0 => { create_title.pop(); },
                                1 => { create_date.pop(); },
                                2 => { create_priority.pop(); },
                                3 => { create_tags.pop(); },
                                _ => {}
                            }
                            continue;
                        },
                        _ => { continue; }
                    }
                }
                // Main key handling
                match key.code {
                    KeyCode::Char('q') => break,
                    KeyCode::Char('?') => { show_help = true; },
                    KeyCode::Char('n') => {
                        show_create = true;
                        create_field = 0;
                        create_title.clear();
                        create_priority.clear();
                        create_tags.clear();
                        create_date = chrono::Local::now().format("%d-%m-%Y").to_string();
                    },
                    KeyCode::Down | KeyCode::Char('j') => {
                        if !entries.is_empty() {
                            selected = (selected + 1).min(entries.len()-1);
                        }
                    },
                    KeyCode::Up | KeyCode::Char('k') => {
                        if selected > 0 { selected -= 1; }
                    },
                    _ => {}
                }
            }
        }
    }
    // Restore terminal
    let _ = crossterm::terminal::disable_raw_mode();
    // Show cursor? ratatui handles?
}

fn centered_rect(percent_x: u16, percent_y: u16, r: ratatui::layout::Rect) -> ratatui::layout::Rect {
    use ratatui::layout::{Constraint, Direction, Layout};
    let popup_layout = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Percentage((100 - percent_y) / 2),
            Constraint::Percentage(percent_y),
            Constraint::Percentage((100 - percent_y) / 2),
        ])
        .split(r);
    Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage((100 - percent_x) / 2),
            Constraint::Percentage(percent_x),
            Constraint::Percentage((100 - percent_x) / 2),
        ])
        .split(popup_layout[1])[1]
}

fn parse_create_date(s: &str) -> DateTime<Utc> {
    // Expect DD-MM-YYYY, else use today midnight UTC
    let s = s.trim();
    if let Ok(d) = chrono::NaiveDate::parse_from_str(s, "%d-%m-%Y") {
        let dt = d.and_hms_opt(0,0,0).unwrap();
        return DateTime::<Utc>::from_naive_utc_and_offset(dt, Utc);
    }
    // Try other formats? For now, today
    let today = chrono::Local::now().date_naive();
    let dt = today.and_hms_opt(0,0,0).unwrap();
    DateTime::<Utc>::from_naive_utc_and_offset(dt, Utc)
}
