import pty, os, subprocess, time, select, struct, fcntl, termios, re, tempfile, json, sqlite3
import tempfile as tf

def run_test(binary, backend, existing_content, import_content=None, assign_prio=None, create_title=None):
    td=tf.mkdtemp()
    h=os.path.join(td,"home")
    os.makedirs(h+"/tui-journal",exist_ok=True)
    logf=os.path.join(td,"mylog.txt")
    if backend=="json":
        entries=os.path.join(td,"entries.json")
        if existing_content is not None:
            open(entries,"w").write(existing_content)
        args=[binary,"--log",logf,"-b","json","-j",entries]
    else:
        db=os.path.join(td,"entries.db")
        entries=db
        if existing_content is not None:
            # existing_content for sqlite? We'll handle separately
            pass
        args=[binary,"--log",logf,"-b","sqlite","-s",db]
    if import_content is not None:
        imp=os.path.join(td,"import.json")
        open(imp,"w").write(import_content)
        args+=["import-journals","-p",imp]
    elif assign_prio is not None:
        args+=["assign-priority",str(assign_prio)]
    # For create test, no extra args, but send keys
    master,slave=pty.openpty()
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH",50,200,0,0))
    env=os.environ.copy(); env.update({"HOME":h,"TERM":"xterm-256color"})
    proc=subprocess.Popen(args,stdin=slave,stdout=slave,stderr=slave,env=env,preexec_fn=os.setsid)
    os.close(slave)
    flags=fcntl.fcntl(master,fcntl.F_GETFL); fcntl.fcntl(master,fcntl.F_SETFL,flags|os.O_NONBLOCK)
    out=b""
    def drain(t=1.5):
        nonlocal out
        s=time.time()
        while time.time()-s<t:
            r,_,_=select.select([master],[],[],0.3)
            if r:
                try:
                    d=os.read(master,65536)
                    if d: out+=d
                except: break
            if proc.poll() is not None: break
    drain(2.5)
    if create_title is not None:
        # send n, type title, Enter, q
        try: os.write(master,b"n")
        except: pass
        drain(1.0)
        try: os.write(master,create_title.encode())
        except: pass
        drain(0.8)
        try: os.write(master,b"\r")  # confirm
        except: pass
        drain(1.0)
        try: os.write(master,b"q")
        except: pass
        drain(1.0)
    else:
        # for import/assign, dismiss error if any then quit
        # try to dismiss with Enter if error popup exists?
        # Just send Enter then q
        try: os.write(master,b"\r")
        except: pass
        drain(0.8)
        try: os.write(master,b"q")
        except: pass
        drain(1.0)
    try:
        if proc.poll() is None:
            proc.terminate(); time.sleep(0.3)
            if proc.poll() is None: proc.kill()
    except: pass
    try: os.close(master)
    except: pass
    try: proc.wait(timeout=2)
    except: pass
    # Read entries file
    try:
        if backend=="json":
            entriesc=open(entries).read() if os.path.exists(entries) else "<no file>"
        else:
            if os.path.exists(entries):
                con=sqlite3.connect(entries)
                cur=con.cursor()
                try:
                    cur.execute("SELECT id, title, date, content, priority FROM entries ORDER BY id")
                    rows=cur.fetchall()
                    cur.execute("SELECT entry_id, tag FROM tags ORDER BY entry_id, tag")
                    tags=cur.fetchall()
                    entriesc=f"rows={rows} tags={tags}"
                except Exception as e:
                    entriesc=f"db err {e}"
            else:
                entriesc="<no file>"
    except Exception as e:
        entriesc=f"read err {e}"
    return entriesc, td

# Test valid import json
import_data=json.dumps({"entries":[{"id":5,"date":"2024-01-01T10:00:00Z","title":"A","content":"a","tags":[],"priority":1}],"version":1})
for binary in ["/workspace/executable","/workspace/target/debug/tui-journal"]:
    entriesc,td=run_test(binary,"json",None,import_content=import_data)
    print(f"valid import {binary.split('/')[-1]}: {entriesc[:200]}")

# Test assign
existing=json.dumps([{"id":0,"date":"2024-01-01T10:00:00Z","title":"H","content":"W","tags":[],"priority":None}])
for binary in ["/workspace/executable","/workspace/target/debug/tui-journal"]:
    entriesc,td=run_test(binary,"json",existing,assign_prio=5)
    print(f"assign {binary.split('/')[-1]}: {entriesc[:200]}")

# Test create
for binary in ["/workspace/executable","/workspace/target/debug/tui-journal"]:
    entriesc,td=run_test(binary,"json",None,create_title="Hello Title")
    print(f"create {binary.split('/')[-1]}: {entriesc[:300]}")
