def run_create(binary, backend):
    td=tf.mkdtemp()
    h=os.path.join(td,"home")
    os.makedirs(h+"/tui-journal",exist_ok=True)
    logf=os.path.join(td,"mylog.txt")
    if backend=="json":
        entries=os.path.join(td,"entries.json")
        args=[binary,"--log",logf,"-b","json","-j",entries]
    else:
        entries=os.path.join(td,"entries.db")
        args=[binary,"--log",logf,"-b","sqlite","-s",entries]
    master,slave=pty.openpty()
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH",50,200,0,0))
    env=os.environ.copy(); env.update({"HOME":h,"TERM":"xterm-256color"})
    proc=subprocess.Popen(args,stdin=slave,stdout=slave,stderr=slave,env=env,preexec_fn=os.setsid)
    os.close(slave)
    flags=fcntl.fcntl(master,fcntl.F_GETFL); fcntl.fcntl(master,fcntl.F_SETFL,flags|os.O_NONBLOCK)
    out=b""
    def drain(t=1.2):
        nonlocal out
        s=time.time()
        while time.time()-s<t:
            r,_,_=select.select([master],[],[],0.3)
            if r:
                try:
                    d=os.read(master,65536)
                    if d: out+=d
                except: break
            if proc.poll() is not None: break
    drain(2.0)
    os.write(master,b"n")
    drain(1.0)
    os.write(master,b"TestTitle")
    drain(0.8)
    os.write(master,b"\r")
    drain(1.0)
    os.write(master,b"q")
    drain(1.0)
